    "settings.panicShake": "ಅಳಿಸಲು ಅಲುಗಾಡಿಸಿ",
    "settings.panicShake.explain": "ಇದು ಅತ್ಯುತ್ತಮ ಪ್ರಯತ್ನ, ಖಾತರಿಯ ಮೌನ ಟ್ರಿಗರ್ ಅಲ್ಲ — ತೀಕ್ಷ್ಣ ಅಲುಗಾಟ (ಉದಾ. ಯಾರಾದರೂ ನಿಮ್ಮ ಫೋನ್ ಕಸಿದುಕೊಂಡಾಗ) ಸಂಕ್ಷಿಪ್ತ, ರದ್ದುಗೊಳಿಸಬಹುದಾದ ಎಚ್ಚರಿಕೆಯನ್ನು ತೋರಿಸುತ್ತದೆ, ನಂತರ ರದ್ದುಗೊಳಿಸದಿದ್ದರೆ ಈ ಸಾಧನವನ್ನು ಅಳಿಸುತ್ತದೆ. ತಪ್ಪು ಎಚ್ಚರಿಕೆಗಳು ಸಾಧ್ಯ; ಅವಲಂಬಿಸುವ ಮೊದಲು ಪರೀಕ್ಷಿಸಿ.",
