    "toast.callGroupsUnsupported": "ಗುಂಪುಗಳಲ್ಲಿ ಕರೆಗಳು ಇನ್ನೂ ಬೆಂಬಲಿತವಾಗಿಲ್ಲ",
    "audio.background.title": "ಸಂಪರ್ಕದಲ್ಲಿದೆ",
    "debug.exportDiagnostics": "ಪೂರ್ಣ ಡಯಾಗ್ನಸ್ಟಿಕ್ಸ್ ರಫ್ತು ಮಾಡಿ (1 ಫೈಲ್)",
