    "chat.contact.identifier.unknown": "ಅಜ್ಞಾತ (ಪರೋಕ್ಷವಾಗಿ ಸೇರಿಸಲಾಗಿದೆ)",
    "call.speaker": "ಸ್ಪೀಕರ್",
    "toast.speakerUnsupported": "ಈ ಬ್ರೌಸರ್ ಆಡಿಯೋ ಔಟ್‌ಪುಟ್ ಬದಲಾಯಿಸುವುದನ್ನು ಬೆಂಬಲಿಸುವುದಿಲ್ಲ",
    "chat.unreadDivider": "ಓದದ ಸಂದೇಶಗಳು",
    "help.start.title": "ಪ್ರಾರಂಭಿಸುವುದು",
    "help.start.body": "The Messenger ನಲ್ಲಿ ಖಾತೆಗಳಿಲ್ಲ ಮತ್ತು ನಿಮ್ಮ ಸಂದೇಶಗಳನ್ನು ಸಂಗ್ರಹಿಸುವ ಕೇಂದ್ರ ಸರ್ವರ್ ಇಲ್ಲ. ಮೊದಲ ಬಾರಿ ಆ್ಯಪ್ ತೆರೆದಾಗ ನೀವು ಹೆಸರು ಆರಿಸುತ್ತೀರಿ (ಫೋನ್ ಸಂಖ್ಯೆ ಅಥವಾ ಇಮೇಲ್ ಐಚ್ಛಿಕ ಮತ್ತು ಅದನ್ನು ಇದ್ದಂತೆಯೇ ಎಲ್ಲಿಗೂ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ). ಯಾರೊಂದಿಗಾದರೂ ಮಾತನಾಡಲು ನೀವಿಬ್ಬರೂ ಒಬ್ಬರನ್ನೊಬ್ಬರು ಸೇರಿಸಬೇಕು: ಆಹ್ವಾನ ಲಿಂಕ್ ಕಳುಹಿಸಿ, QR ಕೋಡ್ ತೋರಿಸಿ ಅಥವಾ ನಿಮ್ಮ ಸಂಪರ್ಕ ಕಾರ್ಡ್ ಹಂಚಿಕೊಳ್ಳಿ.",
    "help.contacts.title": "ಸಂಪರ್ಕಗಳನ್ನು ಸೇರಿಸುವುದು",
    "help.contacts.body": "ಸಂಪರ್ಕಗಳ ಟ್ಯಾಬ್‌ಗೆ ಹೋಗಿ ಮತ್ತು ಇನ್ನೊಬ್ಬರ ಫೋನ್ ಅಥವಾ ಇಮೇಲ್ ನಮೂದಿಸಿ, ಅಥವಾ ಅವರು ಸ್ಕ್ಯಾನ್ ಮಾಡಲು ನಿಮ್ಮ ಸ್ವಂತ ಕೋಡ್ ತೋರಿಸಲು \"ನನ್ನ QR ಕೋಡ್\" ಟ್ಯಾಪ್ ಮಾಡಿ, ಅಥವಾ ಅವರದ್ದನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಲು \"QR ಕೋಡ್ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ\" ಟ್ಯಾಪ್ ಮಾಡಿ. ನೀವು ಈಗಾಗಲೇ ಹೊಂದಿರುವ ಸಂಪರ್ಕವನ್ನು ಚಾಟ್‌ನಿಂದ ನೇರವಾಗಿ ಇನ್ನೊಬ್ಬರಿಗೆ ಫಾರ್ವರ್ಡ್ ಮಾಡಬಹುದು. ಈ ರೀತಿ ಸೇರಿಸಲಾದ ಸಂಪರ್ಕಗಳು (QR, ಫಾರ್ವರ್ಡಿಂಗ್, ಅಥವಾ ಗುಂಪಿನ ಮೂಲಕ) ಅವರ ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿ ಫೋನ್/ಇಮೇಲ್ ತೋರಿಸುವುದಿಲ್ಲ — ಕೇವಲ ಅವರ ಹೆಸರು ಮತ್ತು ಗುರುತಿಸುವಿಕೆ ಮಾತ್ರ — ಇದು ನಿರೀಕ್ಷಿತ, ದೋಷವಲ್ಲ: ಕಚ್ಚಾ ಸಂಪರ್ಕ ಮಾಹಿತಿಯನ್ನು ಈ ರೀತಿ ಎಂದಿಗೂ ರವಾನಿಸಲಾಗುವುದಿಲ್ಲ.",
    "help.messaging.title": "ಸಂದೇಶಗಳನ್ನು ಕಳುಹಿಸುವುದು",
    "help.messaging.body": "ಕೆಳಗಿನ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ ಟೈಪ್ ಮಾಡಿ ಮತ್ತು ಕಳುಹಿಸಿ. ಪ್ರತ್ಯುತ್ತರಿಸಲು, ಕಾಪಿ ಮಾಡಲು, ನಿಮ್ಮ ಸ್ವಂತ ಸಂದೇಶಗಳನ್ನು ಎಡಿಟ್ ಅಥವಾ ಅಳಿಸಲು, ಅಥವಾ ಅವುಗಳನ್ನು ಇನ್ನೊಬ್ಬರಿಗೆ ಫಾರ್ವರ್ಡ್ ಮಾಡಲು ಸಂದೇಶವನ್ನು ಎಡಕ್ಕೆ ಸ್ವೈಪ್ ಮಾಡಿ (ಅಥವಾ ಅದರ ಮೆನು ತೆರೆಯಿರಿ). ಎಮೋಜಿಯೊಂದಿಗೆ ಪ್ರತಿಕ್ರಿಯಿಸಲು ಸಂದೇಶವನ್ನು ದೀರ್ಘವಾಗಿ ಒತ್ತಿ ಅಥವಾ ಟ್ಯಾಪ್ ಮಾಡಿ. ಸಂದೇಶ ಕಳುಹಿಸಲು ವಿಫಲವಾದರೆ, ಅದನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ ಮತ್ತು \"ಮರುಪ್ರಯತ್ನಿಸಿ\" ಆಯ್ಕೆಮಾಡಿ.",
    "help.media.title": "ಫೋಟೋಗಳು, ಫೈಲ್‌ಗಳು ಮತ್ತು ಧ್ವನಿ ಸಂದೇಶಗಳು",
    "help.disappearing.title": "ಮಾಯವಾಗುವ ಸಂದೇಶಗಳು",
    "help.groups.title": "ಗುಂಪು ಚಾಟ್‌ಗಳು",
    "help.calls.title": "ಧ್ವನಿ ಮತ್ತು ವೀಡಿಯೋ ಕರೆಗಳು",
    "help.privacy.title": "ಗೌಪ್ಯತೆ ಮತ್ತು ಭದ್ರತೆ",
    "help.settingsHelp.title": "ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
    "help.settingsHelp.body": "ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ನೀವು ಹೆಸರು, ಭಾಷೆ ಮತ್ತು ನೋಟವನ್ನು (ಬೆಳಕು, ಗಾಢ ಅಥವಾ ಸ್ವಯಂ) ಬದಲಾಯಿಸಬಹುದು. ಧ್ವನಿಗಳು, ಅಧಿಸೂಚನೆಗಳು ಮತ್ತು ಲಿಂಕ್ ಪೂರ್ವವೀಕ್ಷಣೆಗಳನ್ನು ಆನ್ ಅಥವಾ ಆಫ್ ಮಾಡಬಹುದು, ಮತ್ತು ನಿಮ್ಮ ಸಂಪರ್ಕಗಳು ಮತ್ತು ಸಂದೇಶಗಳ ಬ್ಯಾಕಪ್ ಅನ್ನು ರಫ್ತು ಅಥವಾ ಆಮದು ಮಾಡಬಹುದು. ಅಪರೂಪದ ಆಯ್ಕೆಗಳು ಪ್ರತಿ ವಿಭಾಗದೊಳಗಿನ “ಸುಧಾರಿತ” ಅಡಿಯಲ್ಲಿವೆ.",
    "settings.help": "ಸಹಾಯ",
    "settings.pin.disclaimer": "PIN ಪರದೆಯನ್ನು ಆಕಸ್ಮಿಕ ನೋಟದಿಂದ ಮಾತ್ರ ಲಾಕ್ ಮಾಡುತ್ತದೆ — ಈ ಸಾಧನದಲ್ಲಿ ಈಗಾಗಲೇ ಉಳಿಸಲಾದದನ್ನು ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡುವುದಿಲ್ಲ.",
    "settings.pin.change": "PIN ಬದಲಾಯಿಸಿ",
