    "toast.storageFull": "ಸಂಗ್ರಹಣೆ ತುಂಬಿದೆ — ಹೊಸ ಡೇಟಾ ಉಳಿಸುವುದನ್ನು ಮುಂದುವರಿಸಲು ಸ್ಥಳ ಖಾಲಿ ಮಾಡಿ",
    "toast.invalidIdFormat": "ಇದು ಇಮೇಲ್ ಅಥವಾ ಫೋನ್ ಸಂಖ್ಯೆಯಂತೆ ಕಾಣುತ್ತಿಲ್ಲ",
    "toast.badInviteCode": "ಅಮಾನ್ಯ ಅಥವಾ ಅವಧಿ ಮುಗಿದ ಆಹ್ವಾನ ಕೋಡ್",
    "chat.link.open": "ಲಿಂಕ್ ತೆರೆಯಿರಿ",
    "chat.link.copy": "ಲಿಂಕ್ ನಕಲಿಸಿ",
    "toast.inviteFailed": "ಆಹ್ವಾನ ರಚಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ — ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ",
    "debug.exportDataNote": "ಸಂಪರ್ಕಗಳು, ಸಂದೇಶಗಳು ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಒಳಗೊಂಡಿದೆ. ಕಳುಹಿಸಿದ ಅಥವಾ ಸ್ವೀಕರಿಸಿದ ಫೋಟೋಗಳು, ವೀಡಿಯೊಗಳು ಮತ್ತು ಧ್ವನಿ ಸಂದೇಶಗಳು ಈ ಸಾಧನದಲ್ಲಿ ಮಾತ್ರ ಸಂಗ್ರಹವಾಗಿರುತ್ತವೆ ಮತ್ತು ಸೇರಿಸಲಾಗಿಲ್ಲ.",
    "status.rateLimited": "ಹಲವಾರು ಪ್ರಯತ್ನಗಳು",
