    "demo.name": "The Messenger ಮಾರ್ಗದರ್ಶಿ",
    "demo.hint": "ಡೆಮೊ ಚಾಟ್ · ಈ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತದೆ",
    "firstRun.demo": "ಡೆಮೊ ಚಾಟ್ ಪ್ರಯತ್ನಿಸಿ",
    "demo.welcome1": "The Messenger ಗೆ ಸ್ವಾಗತ 👋 ಇದು ಡೆಮೊ ಚಾಟ್ — ಇಲ್ಲಿರುವ ಯಾವುದೂ ನಿಮ್ಮ ಸಾಧನವನ್ನು ಬಿಟ್ಟು ಹೋಗುವುದಿಲ್ಲ.",
    "demo.welcome2": "ಪ್ರಾರಂಭಿಸಲು ನನಗೆ ಏನಾದರೂ ಬರೆಯಿರಿ.",
    "demo.s1": "ಚೆನ್ನಾಗಿದೆ! ಯಾವುದೇ ಸಂದೇಶವನ್ನು ಒತ್ತಿ ಹಿಡಿದು ಪ್ರತಿಕ್ರಿಯಿಸಿ, ಉತ್ತರಿಸಿ ಅಥವಾ ಪಿನ್ ಮಾಡಿ. ಈಗ ಇನ್ನೊಂದನ್ನು ಬರೆಯಿರಿ.",
    "demo.s2": "ಸಮೀಕ್ಷೆ ಅಥವಾ ಬೋರ್ಡ್ ರಚಿಸಲು ಕಂಪೋಸರ್‌ನಲ್ಲಿ + ಟ್ಯಾಪ್ ಮಾಡಿ. ಇಲ್ಲಿ ಉದಾಹರಣೆಗಳಿವೆ — ಮತ ಹಾಕಿ ಮತ್ತು ಕಾರ್ಡ್ ಸರಿಸಿ ನೋಡಿ.",
    "demo.pollQ": "ನಿಮಗೆ ಯಾವ ಥೀಮ್ ಇಷ್ಟ?",
    "demo.pollA": "ಲೈಟ್",
    "demo.pollB": "ಡಾರ್ಕ್",
    "demo.boardTitle": "ಮೊದಲ ಹೆಜ್ಜೆಗಳು",
    "demo.card1": "ನಿಜವಾದ ಸಂಪರ್ಕ ಸೇರಿಸಿ",
    "demo.card2": "ಧ್ವನಿ ಸಂದೇಶ ಪ್ರಯತ್ನಿಸಿ",
    "demo.pollThanks": "ನಿಮ್ಮ ಮತ ಸಿಕ್ಕಿತು! ನಿಜವಾದ ಚಾಟ್‌ನಲ್ಲಿ ಎಲ್ಲರ ಮತಗಳು ಲೈವ್ ಆಗಿ ಕಾಣಿಸುತ್ತವೆ.",
    "demo.boardThanks": "ಬೋರ್ಡ್ ರಚಿಸಲಾಗಿದೆ! ಚಾಟ್‌ನಲ್ಲಿರುವ ಯಾರಾದರೂ ಕಾರ್ಡ್‌ಗಳನ್ನು ಸೇರಿಸಬಹುದು ಮತ್ತು ಸರಿಸಬಹುದು.",
    "demo.s3": "ಧ್ವನಿ ಸಂದೇಶ ರೆಕಾರ್ಡ್ ಮಾಡಲು ಮೈಕ್ ಒತ್ತಿ ಹಿಡಿಯಿರಿ. ರೆಕಾರ್ಡಿಂಗ್ ವಿರಾಮಗೊಳಿಸಬಹುದು, ವೇವ್‌ಫಾರ್ಮ್ ಟ್ಯಾಪ್ ಮಾಡಿ ಸೀಕ್ ಮಾಡಬಹುದು ಮತ್ತು 1× ಬಟನ್‌ನಿಂದ ಪ್ಲೇಬ್ಯಾಕ್ ವೇಗ ಹೆಚ್ಚಿಸಬಹುದು.",
    "demo.s4": "ನಿಜವಾದ ವ್ಯಕ್ತಿಯೊಂದಿಗೆ ಚಾಟ್ ಮಾಡಲು ಸಂಪರ್ಕಗಳನ್ನು ತೆರೆದು ID ಅಥವಾ QR ಕೋಡ್ ಮೂಲಕ ಸೇರಿಸಿ. ಸಂದೇಶಗಳು ಖಾಸಗಿ: ನೀವು ಮತ್ತು ಅವರು ಮಾತ್ರ ಓದಬಹುದು. ಸಿದ್ಧವಾದಾಗ ಮತ್ತೆ ಬರೆಯಿರಿ.",
    "demo.sEnd": "ಪ್ರವಾಸ ಮುಗಿಯಿತು! ಈ ಚಾಟ್ ಅನ್ನು ಯಾವಾಗ ಬೇಕಾದರೂ ಅಳಿಸಬಹುದು: ಪಟ್ಟಿಯಲ್ಲಿ ಅದನ್ನು ಸ್ವೈಪ್ ಮಾಡಿ ಮತ್ತು ಅಳಿಸಿ ಆಯ್ಕೆಮಾಡಿ.",
