    "chat.thread.close": "ಥ್ರೆಡ್ ಮುಚ್ಚಿ",
    "chat.thread.none": "ಇನ್ನೂ ಉತ್ತರಗಳಿಲ್ಲ. ಮೊದಲು ಉತ್ತರಿಸಿ.",
