    "discovery.setting.hint": "ಡೀಫಾಲ್ಟ್ ಆಗಿ ಆಫ್. ಆನ್ ಮಾಡಿದಾಗ ಸರ್ವರ್ ನಿಮ್ಮ ಸಂಖ್ಯೆ/ಇಮೇಲ್‌ನ ಮಿಶ್ರ ರೂಪ, ನಿಮ್ಮ ID ಮತ್ತು ಸಾರ್ವಜನಿಕ ಕೋಡ್ ಅನ್ನು ಮಾತ್ರ ಇಟ್ಟುಕೊಳ್ಳುತ್ತದೆ. ವಿವರಗಳನ್ನು ಓದಲು ಸ್ವಿಚ್ ಒತ್ತಿ.",
    "discovery.findBtn": "ಫೋನ್/ಇಮೇಲ್ ಮೂಲಕ ಹುಡುಕಿ",
    "discovery.title": "ಫೋನ್/ಇಮೇಲ್ ಮೂಲಕ ಹುಡುಕಿ",
    "discovery.explain": "ನಿಮಗೆ ಗೊತ್ತಿರುವವರ ಫೋನ್ ಸಂಖ್ಯೆಗಳನ್ನು (ದೇಶದ ಕೋಡ್‌ನೊಂದಿಗೆ) ಅಥವಾ ಇಮೇಲ್‌ಗಳನ್ನು ನಮೂದಿಸಿ. ನಿಮ್ಮ ಆ್ಯಪ್ ಪ್ರತಿಯೊಂದನ್ನೂ ಮಿಶ್ರ ಮಾಡಿ, ಹುಡುಕಲ್ಪಡಲು ಆರಿಸಿಕೊಂಡವರು ಪ್ರಕಟಿಸಿದವುಗಳಲ್ಲಿ ಯಾವುವು ಇವೆ ಎಂದು ಸರ್ವರ್‌ಗೆ ಕೇಳುತ್ತದೆ. ನೀವು ಹುಡುಕುವ ಸಂಖ್ಯೆಗಳನ್ನು ಸರ್ವರ್ ಎಂದಿಗೂ ನೋಡುವುದಿಲ್ಲ; ಒಪ್ಪಿಗೆ ನೀಡದವರು ಇಲ್ಲಿ ಇಲ್ಲದವರಂತೆಯೇ ಕಾಣುತ್ತಾರೆ. ಮಿತಿಗಳಿವೆ (ಗಂಟೆಗೆ 20 ಹುಡುಕಾಟಗಳು).",
    "discovery.risk": "ಪ್ರಾಮಾಣಿಕ ಎಚ್ಚರಿಕೆ: ಫೋನ್ ಸಂಖ್ಯೆಗಳನ್ನು ಊಹಿಸಬಹುದು. ರಕ್ಷಣೆ ಮತ್ತು ಮಿತಿಗಳು ಸಾಮೂಹಿಕ ಊಹೆಯನ್ನು ನಿಧಾನಗೊಳಿಸುತ್ತವೆ, ಆದರೆ ಅಸಾಧ್ಯಗೊಳಿಸುವುದಿಲ್ಲ. ಆದ್ದರಿಂದಲೇ ಇದು ನಿಮ್ಮ ಆಯ್ಕೆಯಿಂದ ಮಾತ್ರ.",
    "discovery.placeholder": "+49 170 1234567\nfriend@example.com",
    "discovery.pick": "ವಿಳಾಸ ಪುಸ್ತಕದಿಂದ",
    "discovery.search": "ಹುಡುಕಿ",
    "discovery.consent": "ಜನರು ನಿಮ್ಮನ್ನು ಫೋನ್/ಇಮೇಲ್ ಮೂಲಕ ಹುಡುಕಲು ಅವಕಾಶ ನೀಡಬೇಕೆ?\n\nಸರ್ವರ್ ಇವುಗಳನ್ನು ಸಂಗ್ರಹಿಸುತ್ತದೆ: ನಿಮ್ಮ ಸಂಖ್ಯೆ/ಇಮೇಲ್‌ನ ಮಿಶ್ರ ರೂಪ, ನಿಮ್ಮ ID ಮತ್ತು ಸಾರ್ವಜನಿಕ ಕೋಡ್ (ಮತ್ತು ನೀವು ಅನುಮತಿಸಿದರೆ ಮಾತ್ರ ಹೆಸರು), {days} ದಿನಗಳವರೆಗೆ, ನೀವು ಸಂಪರ್ಕಿಸಿದಾಗಲೆಲ್ಲ ನವೀಕರಿಸಲಾಗುತ್ತದೆ. ಬೇರೇನೂ ಇಲ್ಲ; ನಿಮ್ಮ ಸಂಪರ್ಕಗಳು ಮತ್ತು ಸಂದೇಶಗಳು ನಿಮ್ಮ ಸಾಧನವನ್ನು ಎಂದಿಗೂ ಬಿಡುವುದಿಲ್ಲ.\n\nಅಪಾಯ: ನಿಮ್ಮ ಸಂಖ್ಯೆ ಈಗಾಗಲೇ ತಿಳಿದಿರುವ ಯಾರಾದರೂ ನೀವು The Messenger ಬಳಸುತ್ತೀರಾ ಎಂದು ಪರಿಶೀಲಿಸಬಹುದು, ಮತ್ತು ಫೋನ್ ಸಂಖ್ಯೆಗಳನ್ನು ಊಹಿಸಬಹುದು (ರಕ್ಷಣೆ ಮತ್ತು ಮಿತಿಗಳು ಇದನ್ನು ನಿಧಾನಗೊಳಿಸುತ್ತವೆ, ತಡೆಯುವುದಿಲ್ಲ). ಯಾವಾಗ ಬೇಕಾದರೂ ಆಫ್ ಮಾಡಬಹುದು; ದಾಖಲೆ ಅಳಿಸಲಾಗುತ್ತದೆ.",
