    "call.soundProblem": "ಧ್ವನಿ ಸಮಸ್ಯೆಯೇ? ಒತ್ತಿ",
    "call.soundReset": "ಧ್ವನಿಯನ್ನು ಮರುಪ್ರಾರಂಭಿಸಲಾಗಿದೆ",
    "call.micFailed": "ಮೈಕ್ರೊಫೋನ್ ಮರುಪ್ರಾರಂಭಿಸಲು ಆಗಲಿಲ್ಲ — ಆ್ಯಪ್ ಪರದೆಯಲ್ಲಿ ತೆರೆದಿದೆ ಮತ್ತು ಮೈಕ್ರೊಫೋನ್ ಅನುಮತಿ ಇದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ",
    "call.micSuspended": "ನಿಮ್ಮ ಮೈಕ್ರೊಫೋನ್ ಅನ್ನು ಸಿಸ್ಟಂ ವಿರಾಮಗೊಳಿಸಿದೆ. ಇನ್ನೊಬ್ಬರಿಗೆ ನಿಮ್ಮ ಧ್ವನಿ ಕೇಳಲು ಈ ಆ್ಯಪ್ ಅನ್ನು ಪರದೆಯಲ್ಲಿ ತೆರೆದಿಡಿ — ಮರುಪ್ರಾರಂಭಿಸಲು ಒತ್ತಿ",
    "call.peerMicSuspended": "ಈಗ {name} ಅವರ ಧ್ವನಿ ಕೇಳುತ್ತಿಲ್ಲ — ಅವರ ಫೋನ್ ಮೈಕ್ರೊಫೋನ್ ಅನ್ನು ವಿರಾಮಗೊಳಿಸಿದೆ (ಆ್ಯಪ್ ಬಹುಶಃ ಹಿನ್ನೆಲೆಯಲ್ಲಿದೆ). ನೀವು ಮಾತನಾಡುವುದನ್ನು ಮುಂದುವರಿಸಬಹುದು",
    "sigil.pair.hint": "ನಿಮ್ಮಿಬ್ಬರ ಹಂಚಿದ ಗುರುತು — ಎರಡೂ ಫೋನ್‌ಗಳಲ್ಲಿ ಒಂದೇ ಆಗಿರುತ್ತದೆ. ಪರಿಶೀಲಿಸಲು ಒತ್ತಿ",
    "sigil.mine.note": "ಇದು ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಗುರುತು. ಪ್ರತಿ ಚಾಟ್‌ನಲ್ಲಿ ನೀವು ಮತ್ತು ನಿಮ್ಮ ಸಂಪರ್ಕಕ್ಕೆ ಹಂಚಿದ ಗುರುತೂ ಇದೆ — ಅದನ್ನು ಸಂಪರ್ಕ ಕಾರ್ಡ್‌ನಿಂದ ಪರಿಶೀಲಿಸಿ.",
    "sigil.pair.title": "{name} ಪರಿಶೀಲಿಸಿ",
    "sigil.pair.intro": "ನೀವು ಮತ್ತು {name} ಕೆಳಗಿನ ಗುರುತು, ಎಮೋಜಿ ಮತ್ತು ಪದಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಒಂದೇ ರೀತಿ ನೋಡಬೇಕು. ಕರೆ ಮಾಡಿ ಅಥವಾ ಭೇಟಿಯಾಗಿ, ಇದೇ ಪರದೆಯನ್ನು ತೆರೆಯಲು ಹೇಳಿ ಮತ್ತು ಹೋಲಿಸಿ — ಕಣ್ಣಿನಿಂದ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ, ಏನನ್ನೂ ಟೈಪ್ ಮಾಡಬೇಕಿಲ್ಲ.",
    "sigil.pair.emoji": "ಎಮೋಜಿ ಕೋಡ್",
    "sigil.pair.yours": "ನಿಮ್ಮ ಗುರುತು",
    "sigil.pair.theirs": "ಅವರ ಗುರುತು",
    "sigil.pair.ownNote": "ಈ ಎರಡು ಸಣ್ಣ ಗುರುತುಗಳು ವೈಯಕ್ತಿಕ ಮತ್ತು ಯಾವಾಗಲೂ ಬೇರೆಯಾಗಿರುತ್ತವೆ — ಇದು ಸಾಮಾನ್ಯ. ಮೇಲಿನ ದೊಡ್ಡ ಹಂಚಿದ ಗುರುತನ್ನು ಮಾತ್ರ ಹೋಲಿಸಿ.",
    "sigil.pair.copy": "ಕೋಡ್ ನಕಲಿಸಿ",
