    "sigil.pair.matchDone": "ಅದ್ಭುತ — {name} ಪರಿಶೀಲಿಸಲ್ಪಟ್ಟಿದ್ದಾರೆ. ನಿಮ್ಮ ಚಾಟ್ ಅನ್ನು ಯಾರೂ ಕದ್ದಾಲಿಸುತ್ತಿಲ್ಲ.",
    "sigil.pair.differHelp": "ಗುರುತುಗಳು ಬೇರೆಯಾಗಿವೆ. ಈ ಚಾಟ್ ಅನ್ನು ಇನ್ನೂ ನಂಬಬೇಡಿ: ಯಾರಾದರೂ ಕದ್ದಾಲಿಸುತ್ತಿರಬಹುದು ಅಥವಾ ನಿಮ್ಮಿಬ್ಬರಲ್ಲಿ ಒಬ್ಬರಿಗೆ ಬೇರೆ ಸಂಪರ್ಕ ಇರಬಹುದು. ಮತ್ತೊಮ್ಮೆ ಹೋಲಿಸಲು {name} ಅವರಿಗೆ ಹೇಳಿ; ಇನ್ನೂ ಬೇರೆಯಾಗಿದ್ದರೆ ಸಂಪರ್ಕವನ್ನು ಅಳಿಸಿ ಮತ್ತು ಖುದ್ದಾಗಿ ಮತ್ತೆ ಸೇರಿಸಿ.",
