    "idmig.working": "ನಿಮ್ಮ ID ರಕ್ಷಣೆಯನ್ನು ಅಪ್‌ಡೇಟ್ ಮಾಡಲಾಗುತ್ತಿದೆ…",
    "idmig.sheet": "ನಿಮ್ಮ ID ಯ ರಕ್ಷಣೆಯನ್ನು ನಾವು ಬಲಪಡಿಸಿದ್ದೇವೆ. ಮೊದಲು ಸಾಕಷ್ಟು ಬಾರಿ ಪ್ರಯತ್ನಿಸಿದ ಯಾರಾದರೂ ನಿಮ್ಮ ಫೋನ್ ಸಂಖ್ಯೆ ಅಥವಾ ಇಮೇಲ್‌ನಿಂದ ನಿಮ್ಮ ID ಯನ್ನು ಊಹಿಸಬಹುದಿತ್ತು. ಈಗ ಅದನ್ನು ಊಹಿಸುವುದು ತುಂಬಾ ಕಷ್ಟ. ನಿಮ್ಮ ಚಾಟ್‌ಗಳು ಮತ್ತು ಇತಿಹಾಸ ಹಾಗೆಯೇ ಇರುತ್ತವೆ. ಇದು ಈಗಲೂ ನೀವೇ ಎಂಬ ದೃಢೀಕರಣ ನಿಮ್ಮ ಸಂಪರ್ಕಗಳಿಗೆ ಸಿಗುತ್ತದೆ, ಮತ್ತು ಅಪ್‌ಡೇಟ್ ಮಾಡಿದ ಆ್ಯಪ್‌ಗಳಲ್ಲಿ ಸಂಭಾಷಣೆ ಮುಂದುವರಿಯುತ್ತದೆ. ಯಾರಾದರೂ ಇನ್ನೂ ಹಳೆಯ ಆ್ಯಪ್ ಬಳಸುತ್ತಿದ್ದರೆ, ನಿಮ್ಮ ಹಿಂದಿನ ID 90 ದಿನಗಳವರೆಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ; ನಂತರ ನಿಮ್ಮೊಂದಿಗೆ ಮಾತನಾಡಲು ಅವರು ಆ್ಯಪ್ ಅಪ್‌ಡೇಟ್ ಮಾಡಬೇಕು.",
