    "security.version": "ಅಪ್ಲಿಕೇಶನ್ ಆವೃತ್ತಿ",
    "security.state.unconfigured": "ಕಾನ್ಫಿಗರ್ ಆಗಿಲ್ಲ: ಬಿಡುಗಡೆ ಸಹಿ ಇನ್ನೂ ಹೊಂದಿಸಿಲ್ಲ, ಹೀಗಾಗಿ ಅಪ್ಲಿಕೇಶನ್ ತನ್ನನ್ನು ತಾನು ಪರಿಶೀಲಿಸಲಾರದು",
