    "security.state.offline": "ಪರಿಶೀಲಿಸಲಾಗಲಿಲ್ಲ: ಸಂಪರ್ಕವಿಲ್ಲ",
    "security.check": "ಈಗ ಪರಿಶೀಲಿಸಿ",
    "security.check.aria": "ಅಪ್ಲಿಕೇಶನ್ ಸಮಗ್ರತೆಯನ್ನು ಈಗ ಪರಿಶೀಲಿಸಿ",
    "security.updateRejected": "ನವೀಕರಣ ಸಹಿ ಪರಿಶೀಲನೆಯಲ್ಲಿ ವಿಫಲವಾಯಿತು",
    "security.protects": "ಯಾವುದು ರಕ್ಷಿತ",
    "security.notProtects": "ಯಾವುದು ರಕ್ಷಿತವಲ್ಲ",
    "security.protect.1": "ಸಂದೇಶ ಮತ್ತು ಫೈಲ್‌ಗಳ ವಿಷಯ ಎಂಡ್-ಟು-ಎಂಡ್ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿದೆ: ಸರ್ವರ್‌ಗಳು ಮತ್ತು ನೆಟ್‌ವರ್ಕ್ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ ಪಠ್ಯವನ್ನು ಮಾತ್ರ ನೋಡುತ್ತವೆ.",
    "security.protect.2": "ಚಾಟ್ ಮಾಡುವಾಗ ಕೀಗಳು ಬದಲಾಗುತ್ತವೆ, ಹೀಗಾಗಿ ನಂತರ ಕದ್ದ ಕೀ ನೀವು ಈಗಾಗಲೇ ಓದಿದ ಸಂದೇಶಗಳನ್ನು ತೆರೆಯಲಾರದು.",
    "security.protect.3": "ಸಂಪರ್ಕದ ಕೀ ಬದಲಾದರೆ, ನೀವು ದೃಢೀಕರಿಸುವವರೆಗೆ ಕರೆಗಳು ನಿರ್ಬಂಧಿತ. ರೂನ್ ಅಥವಾ ಸುರಕ್ಷತಾ ಸಂಖ್ಯೆಯನ್ನು ನೇರವಾಗಿ ಅಥವಾ ಧ್ವನಿಯಲ್ಲಿ ಹೋಲಿಸಿ ಸಂಪರ್ಕಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.",
    "security.protect.4": "ನಿಮ್ಮ ಸಂದೇಶಗಳು ಮತ್ತು ಸಂಪರ್ಕಗಳನ್ನು ಯಾವುದೇ ಸರ್ವರ್‌ನಲ್ಲಿ ಓದಬಹುದಾದ ರೂಪದಲ್ಲಿ ಇಡುವುದಿಲ್ಲ; ಸರ್ವರ್ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ ಅಂಚೆಯನ್ನು ತೆಗೆದುಕೊಳ್ಳುವವರೆಗೆ ಮಾತ್ರ ಇಟ್ಟುಕೊಳ್ಳುತ್ತದೆ.",
    "security.protect.5": "ಬಿಡುಗಡೆ ಸಹಿ ಕಾನ್ಫಿಗರ್ ಆಗಿದ್ದರೆ, ಸಹಿ ಪರಿಶೀಲನೆಯಲ್ಲಿ ವಿಫಲವಾದ ನವೀಕರಣ ಇನ್‌ಸ್ಟಾಲ್ ಆಗುವುದಿಲ್ಲ ಮತ್ತು ಹಳೆಯ ಆವೃತ್ತಿ ಕೆಲಸ ಮುಂದುವರಿಸುತ್ತದೆ.",
    "security.not.1": "ಯಾರು ಯಾರೊಂದಿಗೆ, ಯಾವಾಗ ಮತ್ತು ಯಾವ ನೆಟ್‌ವರ್ಕ್ ವಿಳಾಸದಿಂದ ಮಾತನಾಡುತ್ತಾರೆ ಎಂಬುದು ಸರ್ವರ್‌ಗಳು ಮತ್ತು ನೆಟ್‌ವರ್ಕ್‌ಗೆ ಕಾಣುತ್ತದೆ (ಮೆಟಾಡೇಟಾ).",
    "security.not.2": "ಅನ್‌ಲಾಕ್ ಆದ, ವಶಪಡಿಸಿಕೊಂಡ ಅಥವಾ ಸೋಂಕಿತ ಫೋನ್ ಅಥವಾ ಕಂಪ್ಯೂಟರ್: ಸಾಧನವನ್ನು ನಿಯಂತ್ರಿಸುವವರು ನೀವು ಓದುವುದನ್ನು ಓದಬಲ್ಲರು.",
    "security.not.3": "ನೀವು ಪರಿಶೀಲಿಸದ ಸಂಪರ್ಕ ವಂಚಕರಾಗಿರಬಹುದು; ಮೊದಲ ಸಂಪರ್ಕವನ್ನು ನೀವು ಪರಿಶೀಲಿಸಿದಷ್ಟೇ ನಂಬಲಾಗುತ್ತದೆ.",
    "security.not.4": "ನಿಮ್ಮ ಸಂಪರ್ಕಗಳು ನೀವು ಕಳುಹಿಸಿದ್ದನ್ನು ನಕಲಿಸಬಹುದು, ಫಾರ್ವರ್ಡ್ ಮಾಡಬಹುದು ಅಥವಾ ಫೋಟೋ ತೆಗೆಯಬಹುದು.",
    "security.not.5": "ಮೊದಲ ಇನ್‌ಸ್ಟಾಲ್: ಇನ್‌ಸ್ಟಾಲ್ ಮೊದಲೇ ಹೋಸ್ಟಿಂಗ್ ಅಥವಾ ಡೌನ್‌ಲೋಡ್ ದುರುದ್ದೇಶದ್ದಾಗಿದ್ದರೆ, ಅಪ್ಲಿಕೇಶನ್ ಒಳಗಿನಿಂದ ಅದನ್ನು ಪತ್ತೆ ಮಾಡಲಾರದು.",
    "security.not.6": "ನಿರ್ಬಂಧ: ಎಲ್ಲಾ ಸರ್ವರ್‌ಗಳನ್ನು ಅಥವಾ ಇಡೀ ನೆಟ್‌ವರ್ಕ್ ಅನ್ನು ನಿರ್ಬಂಧಿಸುವ ಸೆನ್ಸಾರ್ ಅಪ್ಲಿಕೇಶನ್ ಸಂಪರ್ಕಿಸುವುದನ್ನು ತಡೆಯಬಲ್ಲರು.",
    "security.not.7": "ಸ್ವತಂತ್ರ ಭದ್ರತಾ ಪರಿಶೋಧನೆ ಇನ್ನೂ ನಡೆದಿಲ್ಲ; ದೋಷಗಳಿರಬಹುದು.",
    "security.contacts": "ಸಂಪರ್ಕ ಪರಿಶೀಲನೆ",
